import{_ as i,o as a,c as r,a3 as t}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"息壤气\\\\酸气串行","description":"","frontmatter":{"translationSource":{"title":"息壤气\\\\酸气串行","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=QSB4bZ80E13jewhwgGVnJ4","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/xiragen-acridgen-in-series"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/xiragen-acridgen-in-series"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/xiragen-acridgen-in-series"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/xiragen-acridgen-in-series"}]]},"headers":[],"relativePath":"zh/xiragen-acridgen-in-series.md","filePath":"zh/page-QSB4bZ80E13jewhwgGVnJ4.md"}'),n={name:"zh/xiragen-acridgen-in-series.md"};function o(s,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<div class="logistics-content"><h1 id="息壤气-酸气串行" tabindex="-1">息壤气\\酸气串行 <a class="header-anchor" href="#息壤气-酸气串行" aria-label="Permalink to &quot;息壤气\\\\酸气串行&quot;">​</a></h1><blockquote><p>源页面 ID：<code>QSB4bZ80E13jewhwgGVnJ4</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=QSB4bZ80E13jewhwgGVnJ4" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>结构由 断懒 提供，如图所示</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fefee1e7bfaba543.q90-c91b02db3e91c618.webp" alt="息壤气酸气串行"></p><p>考虑到酸气消耗极慢，息壤气消耗极快，生产酸气会有一段堵得时间，生产息壤气则可以视为立刻输出。</p><p>酸液几乎总是只会进入一到二滴转化为酸气，而后切换为息壤液输入。</p><p>在生产的酸气尚未输出时，有转化机内50的缓冲，足以缓冲整整2min的息壤液输入。</p><p>在此期间一旦酸气消耗，息壤液就开始以30/min的速度转化为息壤气并输出，30消耗&gt;24输入，最终息壤液会消耗殆尽。</p><p>随后已经堵在入口的酸液会进入转化机，进入新的循环。</p></div>',1)])])}const f=i(n,[["render",o]]);export{g as __pageData,f as default};
